from typing import TypedDict, List

class SimulationState(TypedDict):
    # Captures the user's input (e.g., "Ban all gas cars in the city center")[cite: 1].
    policy_proposal: str
    
    # A list appended to by the swarm agents containing their exact loophole strategies[cite: 1].
    demographic_actions: List[dict]
    
    # The final vulnerability report generated by the Evaluator[cite: 1].
    environmental_impact: str
    
    # Feeds directly into PyDeck in Step 5 to render the 3D heatmap dynamically[cite: 1].
    city_grid_state: List[list]
    
    # Tracks iterations if the policy maker chooses to dynamically edit and rerun the simulation[cite: 1].
    loop_count: int
  
